package com.xuhang.mealops.inventory.domain;
import static org.assertj.core.api.Assertions.*; import java.math.*; import java.util.*; import org.junit.jupiter.api.Test; import com.xuhang.mealops.measurement.domain.*;
class InventoryConsumptionPlanInvariantTest { private InventoryConsumptionAllocation a(int p,long id,String amount,String before,String after,String unit){return new InventoryConsumptionAllocation(p,id,0,new BigDecimal(amount),new BigDecimal(before),new BigDecimal(after),unit);} private InventoryConsumptionAllocation av(int p,long id,long version,String amount,String before,String after,String unit){return new InventoryConsumptionAllocation(p,id,version,new BigDecimal(amount),new BigDecimal(before),new BigDecimal(after),unit);} @Test void allocationRejectsInvalidState(){assertThatThrownBy(()->a(0,1,"1","1","0","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,0,"1","1","0","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->av(1,1,-1,"1","1","0","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,1,"0","1","1","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,1,"1","-1","0","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,1,"1","1","-1","g")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,1,"1","1","0","kg")).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->a(1,1,"1","1","1","g")).isInstanceOf(InvalidInventoryBatchException.class);} @Test void planEnforcesContinuousPositionsUnitsAndExactSum(){var q=Quantity.of(new BigDecimal("2"),Unit.GRAM);assertThatThrownBy(()->new InventoryConsumptionPlan(q,List.of(a(2,1,"1","1","0","g"),a(1,2,"1","1","0","g")))).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->new InventoryConsumptionPlan(q,List.of(a(1,1,"1","1","0","g"),a(1,2,"1","1","0","g")))).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->new InventoryConsumptionPlan(q,List.of(a(1,1,"1","1","0","g"),a(3,2,"1","1","0","g")))).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->new InventoryConsumptionPlan(q,List.of(a(1,1,"1","1","0","g"),a(2,2,"2","2","0","g")))).isInstanceOf(InvalidInventoryBatchException.class);assertThatThrownBy(()->new InventoryConsumptionPlan(q,List.of(a(1,1,"1","1","0","g"),a(2,2,"1","1","0","ml")))).isInstanceOf(InvalidInventoryBatchException.class);var p=new InventoryConsumptionPlan(q,List.of(a(1,1,"1","1","0","g"),a(2,2,"1","1","0","g")));assertThatThrownBy(()->p.allocations().clear()).isInstanceOf(UnsupportedOperationException.class);} }
